<?php
declare(strict_types=1);
require_once __DIR__.'/../app/view.php';
try{$path=trim((string)(parse_url($_SERVER['REQUEST_URI']??'',PHP_URL_PATH)??''),'/');$slug=(string)($_GET['slug']??basename($path));if(!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/D',$slug))throw new RuntimeException();$db=shop_db();$q=$db->prepare('SELECT id,name,description FROM shop_categories WHERE slug=? AND active=1');$q->execute([$slug]);$cat=$q->fetch();if(!$cat)throw new RuntimeException();}catch(Throwable $e){$missing=$e instanceof RuntimeException;http_response_code($missing?404:503);cp_public_header('دسته‌بندی در دسترس نیست');echo '<p class="empty">'.($missing?'دسته‌بندی پیدا نشد.':'ارتباط با فروشگاه موقتاً برقرار نیست.').'</p>';cp_public_footer();exit;}
$products=$db->prepare('SELECT id,slug,name,price,image_url FROM shop_products WHERE published=1 AND (category_id=? OR category_id IN(SELECT id FROM shop_categories WHERE parent_id=?)) ORDER BY featured DESC,updated_at DESC LIMIT 100');$products->execute([$cat['id'],$cat['id']]);
cp_public_header($cat['name'],$cat['description'],rtrim((string)cp_cfg('public_base_url','https://shop.mycablog.dandoonii.ir'),'/').'/collection/'.$slug.'/',cp_cfg('test_mode',true)?'noindex,nofollow':'index,follow');
echo '<nav class="breadcrumbs"><a href="/">خانه</a> / '.cp_h($cat['name']).'</nav><section class="block-section"><div class="block-heading"><h1>'.cp_h($cat['name']).'</h1><p>'.cp_h($cat['description']).'</p></div><div class="product-grid">';foreach($products->fetchAll() as $p)echo cp_card($p);echo '</div></section>';cp_public_footer();
